/* First-person discovery: four visible roads, normal answer buttons, and an optional lantern cursor. */
const RoadQuiz={routes:[{path:'M800 680C705 587 502 475 240 325',hit:'M628 542C508 475 370 398 240 325',x:18,y:61,turn:-1},{path:'M800 680C766 552 663 419 605 305',hit:'M734 504C684 420 641 362 605 305',x:39,y:50,turn:-.4},{path:'M800 680C834 552 937 419 995 305',hit:'M866 504C916 420 959 362 995 305',x:61,y:50,turn:.4},{path:'M800 680C895 587 1098 475 1360 325',hit:'M972 542C1092 475 1230 398 1360 325',x:82,y:61,turn:1}],chapters:['The first light','Follow your curiosity','A direction emerges','Beyond the bend']};
function roadLanternSVG(name='held'){return `<svg viewBox="0 0 140 190" aria-hidden="true"><defs><radialGradient id="hand-lantern-light-${name}"><stop stop-color="#ffe9a4" stop-opacity=".95"/><stop offset=".25" stop-color="#ffcf7566"/><stop offset="1" stop-color="#ffcf7500"/></radialGradient><linearGradient id="hand-sleeve-${name}" x2="1" y2="1"><stop stop-color="#4a3751"/><stop offset="1" stop-color="#171a27"/></linearGradient></defs><circle cx="67" cy="76" r="65" fill="url(#hand-lantern-light-${name})"/><path d="M79 186L54 144 46 126l14-17 21 5 18 35 27 37" fill="url(#hand-sleeve-${name})" stroke="#776181" stroke-width="1.5"/><path d="M55 131l-7-16 2-17 9-8 7 6 5-4 7 4 2 13-11 12-4 15Z" fill="#b78d77" stroke="#dfb092" stroke-width="1"/><path d="M48 36V24a18 18 0 0136 0v12" fill="none" stroke="#d8bb86" stroke-width="4"/><path d="M43 41l23-11 23 11-5 54-18 13-18-13Z" fill="#1c2630" stroke="#c5a675" stroke-width="3"/><path d="M51 49l15-7 15 7-4 39-11 9-11-9Z" fill="#f9d48e" fill-opacity=".84"/><path d="M66 43v53M48 42h36m-33 47h30" stroke="#856f4c" stroke-width="3"/><path class="road-lantern-flame" d="M65 83c-10-10 8-16 2-25 13 13 8 18 1 25Z" fill="#fff8d1"/></svg>`}
function roadScene(chapter=0){const trees=Array.from({length:23},(_,i)=>{const side=i%2===0?-1:1,depth=(i%12)/12,scale=.35+depth*1.5,x=800+side*(260+depth*590),y=308+depth*395;return `<g transform="translate(${x.toFixed(1)} ${y.toFixed(1)}) scale(${scale.toFixed(2)})" opacity="${(.22+depth*.6).toFixed(2)}"><path d="M-5 0l2-167 8-6 4 173Z"/><path d="M1-135l-26-38m29 20l24-45m-26 95l-38-30m44 17l30-31" fill="none" stroke="currentColor" stroke-width="5"/><path d="M-52-145l53-117 53 117-24-12 28 43-36-14 34 44-55-17-48 17 33-44-34 14 27-43Z"/></g>`}).join('');return `<div class="road-world" data-road-world data-chapter="${chapter}" aria-hidden="true"><svg viewBox="0 0 1600 900" preserveAspectRatio="xMidYMid slice" class="road-landscape"><defs><linearGradient id="road-sky" x2="0" y2="1"><stop stop-color="#101829"/><stop offset=".48" stop-color="#39314d"/><stop offset="1" stop-color="#605360"/></linearGradient><linearGradient id="road-earth" x2="0" y2="1"><stop stop-color="#343541"/><stop offset="1" stop-color="#10191f"/></linearGradient><linearGradient id="road-stone" x1="0" y1="1" x2="0" y2="0"><stop stop-color="#746a72"/><stop offset="1" stop-color="#88808b"/></linearGradient><radialGradient id="road-moon"><stop stop-color="#e6d8c4" stop-opacity=".3"/><stop offset="1" stop-color="#e6d8c4" stop-opacity="0"/></radialGradient><radialGradient id="road-foreground-light"><stop stop-color="#f0cf8b" stop-opacity=".22"/><stop offset="1" stop-color="#f0cf8b" stop-opacity="0"/></radialGradient></defs><rect width="1600" height="900" fill="url(#road-sky)"/><circle cx="806" cy="215" r="165" fill="url(#road-moon)"/><circle class="road-moon" cx="806" cy="215" r="27"/><path d="M0 360Q170 270 345 355T800 327T1250 354T1600 300V540H0Z" fill="#202736"/><path d="M0 410Q280 308 455 375T900 353T1300 379T1600 345V900H0Z" fill="url(#road-earth)"/><g class="road-distant-trees">${trees}</g><g class="road-forks">${RoadQuiz.routes.map((r,i)=>`<g class="road-route road-route-${i}" data-road-route="${i}"><path class="road-route-shadow" d="${r.path}"/><path class="road-route-surface" d="${r.path}"/><path class="road-route-edge" d="${r.path}"/><path class="road-route-glow" d="${r.path}"/><path class="road-hit" data-road-fork="${i}" d="${r.hit}"/></g>`).join('')}</g><path class="road-trunk-shadow" d="M800 662C812 750 804 828 800 1050"/><path class="road-trunk" d="M800 662C812 750 804 828 800 1050"/><g class="road-paving"><path d="M550 864l450 0M599 803h405M665 749h280M711 707h185M753 677h102"/><path d="M800 681v24m-42 8l-6 36m101-36l8 36m-124 11l-17 43m170-43l19 43m-156 12l-9 49m112-49l10 49"/></g><ellipse cx="800" cy="890" rx="400" ry="230" fill="url(#road-foreground-light)"/><g class="road-foreground-leaves"><path d="M0 900V480l80 117 52-31 75 140 95-14 92 208Zm1600 0V480l-80 117-52-31-75 140-95-14-92 208Z"/></g><g class="road-fireflies">${Array.from({length:18},(_,i)=>`<circle cx="${160+(i*211)%1280}" cy="${190+(i*67)%440}" r="${i%4===0?2:1}" style="--firefly:${i}"/>`).join('')}</g></svg><div class="road-fog fog-one"></div><div class="road-fog fog-two"></div><div class="road-walk-shade"></div></div>`}
function firstPersonQuestion(){if(!answers.length&&quizIndex===0)restoreQuiz();if(quizIndex>=quizLength)quizIndex=quizLength-1;const q=ProductCore.questions[quizIndex],chapter=Math.min(3,Math.floor(quizIndex/quizLength*4));journeyLastQuizIndex=quizIndex;return `<section class="quiz journey-quiz road-quiz" data-first-person data-quiz-chapter="${chapter}" style="--road-choice-color:#f2d49b">${roadScene(chapter)}<div class="road-vignette" aria-hidden="true"></div><div class="road-quiz-topline"><a class="journey-secondary" href="#discover">← Save & leave</a><span class="road-chapter">${RoadQuiz.chapters[chapter]}</span><div class="road-controls"><span>${quizIndex+1} / ${quizLength}</span><button class="motion-control" data-toggle-motion>${journeyReduced()?'Motion off':'Motion on'}</button><button class="motion-control" id="lantern-cursor-toggle" aria-pressed="${!state.standardCursor}">${state.standardCursor?'Lantern cursor off':'Lantern cursor on'}</button></div></div><div class="road-question"><span class="eyebrow">A FORK IN YOUR FUTURE · CHAPTER ${chapter+1}</span><h1 id="quiz-prompt" tabindex="-1">${esc(q.prompt)}</h1><p>Bring your light to a path. Click to choose it.</p></div><div class="road-choices choices" role="group" aria-labelledby="quiz-prompt">${q.choices.map((label,i)=>`<button class="road-sign choice ${answers[quizIndex]===q.tags[i]?'selected':''}" style="--sign-x:${RoadQuiz.routes[i].x}%;--sign-y:${RoadQuiz.routes[i].y}%;--path-index:${i}" data-product-answer="${q.tags[i]}" data-road-choice="${i}" aria-pressed="${answers[quizIndex]===q.tags[i]}"><span class="road-sign-post" aria-hidden="true"></span><span class="road-sign-face"><span class="road-choice-number">0${i+1}</span><span class="choice-copy">${esc(label)}</span><span class="road-sign-arrow" aria-hidden="true">${i<2?'↖':'↗'}</span></span></button>`).join('')}</div><div class="road-confirmation" id="road-confirmation" role="status" aria-live="polite"></div><div class="road-held-lantern" aria-hidden="true">${roadLanternSVG()}</div><div class="road-lantern-cursor" id="road-lantern-cursor" aria-hidden="true"><span class="road-cursor-hotspot"></span>${roadLanternSVG('cursor')}</div><div class="road-quiz-bottom"><button class="journey-secondary" id="product-quiz-back" ${quizIndex===0?'disabled':''}>← Previous fork</button><span class="road-keyboard-hint">Choose a sign or a road · keys 1–4 work too</span><div class="road-progress" role="progressbar" aria-label="Quiz progress" aria-valuemin="0" aria-valuemax="${quizLength}" aria-valuenow="${quizIndex}" style="--progress:${quizIndex/quizLength}"><span></span></div></div><details class="road-about"><summary>About this journey</summary><p>No time limit or speed scoring. Choose with a mouse, touch, Tab/Enter, or keys 1–4. The lantern is optional. Interests guide exploratory recommendations, not ability scores or admissions predictions.</p></details></section>`}
function bindRoadQuiz(){const root=document.querySelector('[data-first-person]');if(!root)return;const buttons=[...root.querySelectorAll('[data-road-choice]')],world=root.querySelector('[data-road-world]');const illuminate=(index)=>{if(journeyQuizBusy)return;const button=buttons[index];if(!button)return;root.dataset.activeRoad=String(index);root.style.setProperty('--road-choice-color',QuizWorld.themes[button.dataset.productAnswer]?.[0]||'#f2d49b');root.style.setProperty('--walk-direction',RoadQuiz.routes[index].turn);root.querySelector('#road-confirmation').textContent='';};buttons.forEach((button,index)=>{button.onfocus=()=>illuminate(index);button.onpointerenter=()=>illuminate(index);const commit=button.onclick;button.onclick=async event=>{if(journeyQuizBusy)return;illuminate(index);root.dataset.chosenRoad=String(index);root.querySelector('#road-confirmation').textContent='Path chosen: '+button.querySelector('.choice-copy').textContent;world.classList.add('road-walking');await commit?.(event)}});root.querySelectorAll('[data-road-fork]').forEach(path=>{path.onpointerenter=()=>illuminate(+path.dataset.roadFork);path.onclick=()=>buttons[+path.dataset.roadFork]?.click()});root.addEventListener('pointermove',event=>{if(event.pointerType==='touch'||journeyReduced()||state.standardCursor)return;const rect=root.getBoundingClientRect();const x=event.clientX-rect.left,y=event.clientY-rect.top;root.style.setProperty('--lantern-x',x+'px');root.style.setProperty('--lantern-y',y+'px');root.classList.add('lantern-pointer-active')},{passive:true});root.addEventListener('pointerleave',()=>root.classList.remove('lantern-pointer-active'));root.addEventListener('pointerdown',event=>{if(event.pointerType==='touch')root.classList.remove('lantern-pointer-active')},{passive:true});root.querySelector('#lantern-cursor-toggle').onclick=()=>{state.standardCursor=!state.standardCursor;save();render()};}
function firstPersonDiscover(){let draft;try{draft=ProductCore.quizDraft(JSON.parse(sessionStorage.getItem('camino-quiz-session')||'null')||state.quizDraft)}catch{}return journeyPage(1,'Your direction starts at a fork.',`<p class="journey-lede">Follow your curiosity. Let each choice light the way.</p><div class="road-invitation">${roadScene(0)}<div class="road-invitation-copy"><span class="eyebrow">YOUR LIGHT. YOUR PATH.</span><h2>There’s more than one way forward.</h2><p>12 small choices. Four roads at each fork. No right answers, no rush.</p>${draft&&draft.answers.length<draft.length?`<button class="btn primary" id="resume-quiz">Continue my journey →</button><p class="quiet-note">${draft.answers.length} of ${draft.length} answered.</p><button class="journey-secondary" data-start="12">Start again</button>`:'<button class="btn primary" data-start="12">Pick up the lantern →</button>'}<details class="quiet-options"><summary>Take the longer road</summary><p>Explore 32 situations instead.</p><button class="btn" data-start="32">Begin 32 questions</button></details></div><div class="road-invitation-lantern" aria-hidden="true">${roadLanternSVG('invitation')}</div></div><a class="journey-secondary" href="#profile">Already know your direction? Build a plan.</a><details class="journey-footnote"><summary>How it works</summary><p>A first-person road through your interests. Click a road or its sign to confirm your choice and move to the next fork. Your answers save for this session. The quiz is exploratory and does not predict admission. Motion and the custom cursor are optional.</p></details>`,'home')}
function installRoadQuiz(){question=firstPersonQuestion;discover=firstPersonDiscover;const before=bind;bind=()=>{before();bindRoadQuiz()}}
